    }

    switch (_rule)
    {
        case EXU_AlternativeCustomerCodeValidationRule::Da:
            return XAPI_AlternativeCustomerNumberGenerator::generateDanishCVR();
        case EXU_AlternativeCustomerCodeValidationRule::Sv:
            return XAPI_AlternativeCustomerNumberGenerator::generateSwedishCVR();
        default:
            throw Error(Error::wrongUseOfFunction(funcName()));
            return "";
    }
}
